//! Recorded OpenSSL `s_client` and Go crypto/tls client sessions against
//! `Server`, written by `tools/interop.zig --capture` (OpenSSL 3.5, Go
//! 1.26). Each case: the server's
//! configuration and seed, every octet the client sent, every octet the
//! server sent. Replayed by `interop_replay_test.zig`. Do not edit by hand.

pub const CertKind = enum { p256, p384, ed25519, rsa2048, p521, mldsa65 };
pub const ClientCertKind = enum { none, p256, rsa2048, ed25519 };
pub const ClientAuthMode = enum { off, mandatory, optional };
/// The ticket key and the clock of the `tickets` cases.
pub const stek_key: [32]u8 = @splat(0x5e);
pub const clock_ms: i64 = 1800000000000;
/// `EarlyData.max_size` of the `early_data` cases.
pub const max_early_data: u32 = 16384;
/// The QUIC cases' transport parameters, the server's and the client's.
pub const quic_server_tp = hx(12, "0404801000000f0453525631");
pub const quic_client_tp = hx(12, "0404800800000f04434c4931");
/// The exporter label and length of the cases with `exported`.
pub const exporter_label = "EXPERIMENTAL-tlsserver-interop";
pub const exporter_len = 48;
/// The ECH private key of the `ech` cases.
pub const ech_key: [32]u8 = @splat(0x45);
/// The leaf's OCSP staple and SCT list in the `staple` cases.
pub const ocsp_response = hx(5, "30030a0101");
pub const sct_list = hx(18, "001000075343542d6f6e6500055343542d32");

pub const Case = struct {
    name: []const u8,
    cert: CertKind,
    seed: u8,
    suites: []const u16,
    groups: []const u16,
    alpn: []const []const u8,
    /// The server sent KeyUpdate(update_requested) before "pong\n".
    key_update: bool = false,
    /// Tickets under `stek_key` (id 1) with the clock at `clock_ms`.
    tickets: bool = false,
    /// The server resumed a session.
    resumed: bool = false,
    /// Client certificates through the test client CA (`client_certs.zig`).
    client_auth: ClientAuthMode = .off,
    /// The server's `peerCertificate` at the end.
    client_cert: ClientCertKind = .none,
    /// RFC 7250: the server's key went as its bare SubjectPublicKeyInfo.
    raw_server: bool = false,
    /// RFC 7250: the client's `client_cert` went as its SPKI, taken by an
    /// allowlist of that key.
    raw_client: bool = false,
    /// QUIC (`Config.quic`, `quic_server_tp`): `client` and `server` are
    /// frames of a level octet, a 4-octet big-endian length and the
    /// handshake data at that level.
    quic: bool = false,
    /// QUIC: `Quic.accept_early` vetoed the ticket's resumption data (the
    /// tickets carry `quic_server_tp`).
    quic_veto: bool = false,
    /// QUIC: the server's handshake traffic secret (`quicSecret(.write,
    /// .handshake)`), as the client installed it to read.
    quic_server_hs: ?[]const u8 = null,
    /// The leaf carried `ocsp_response` and `sct_list`.
    staple: bool = false,
    /// The leaf's Certificate (no staples) also went as this
    /// CompressedCertificate to a client that offered its algorithm.
    compressed: ?Compressed = null,
    /// The server took early data (`max_early_data`).
    early_data: bool = false,
    /// It took the client's ("ping\\n").
    early_accepted: bool = false,
    /// The server's keying material for `exporter_label` (no context),
    /// which the client printed too.
    exported: ?[exporter_len]u8 = null,
    /// RFC 9849: the server held `ech_key` (config id 7, public name
    /// "public.example") and accepted the client's encrypted hello.
    ech: bool = false,
    client: []const u8,
    server: []const u8,
};

pub const Compressed = struct { algorithm: u16, uncompressed_len: u24, data: []const u8 };

